 *
 * <p>Every problem in the file is collected and reported together in one {@link ConfigException}. A missing,
 * misspelled, or malformed value is never replaced by a default; only keys that are absent get their default.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();

        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add("unknown key '" + key + "' (check the spelling; known keys are " + KNOWN_KEYS_LIST + ")");
            }
        }

        URI upstream = upstream(properties, problems);
        String apiToken = apiToken(properties, problems);
        int workerThreads = integer(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = integer(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = integer(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = requestTimeout(properties, problems);
        boolean metricsEnabled = bool(properties, "metrics.enabled", false, problems);

        if (!problems.isEmpty()) {
            throw new ConfigException(describe(file, problems));
        }
        return new ServiceConfig(
                upstream, apiToken, workerThreads, queueCapacity, retryAttempts, requestTimeout, metricsEnabled);
    }

    private static final String KNOWN_KEYS_LIST = String.join(", ", new TreeSet<>(KNOWN_KEYS));

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
