        String raw = properties.getProperty("upstream.url");
        if (raw == null || raw.isBlank()) {
            problems.add("upstream.url is required");
            return null;
        }
        String text = raw.trim();
        try {
            URI uri = new URI(text);
            boolean httpScheme = "http".equalsIgnoreCase(uri.getScheme()) || "https".equalsIgnoreCase(uri.getScheme());
            if (!httpScheme || uri.getHost() == null) {
                problems.add("upstream.url must be an absolute http or https URL with a host, got '" + text + "'");
                return null;
