package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Every problem in the file is collected and reported together in one {@link ConfigException}. A missing,
 * misspelled, or malformed value is never replaced by a default; only keys that are absent get their default.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();

        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add("unknown key '" + key + "' (check the spelling; known keys are " + KNOWN_KEYS_LIST + ")");
            }
        }

        URI upstream = upstream(properties, problems);
        String apiToken = apiToken(properties, problems);
        int workerThreads = integer(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = integer(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = integer(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = requestTimeout(properties, problems);
        boolean metricsEnabled = bool(properties, "metrics.enabled", false, problems);

        if (!problems.isEmpty()) {
            throw new ConfigException(describe(file, problems));
        }
        return new ServiceConfig(
                upstream, apiToken, workerThreads, queueCapacity, retryAttempts, requestTimeout, metricsEnabled);
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("cannot read configuration file " + file.toAbsolutePath() + ": " + e.getMessage());
        }
        return properties;
    }

    private static URI upstream(Properties properties, List<String> problems) {
        String raw = properties.getProperty("upstream.url");
        if (raw == null || raw.isBlank()) {
            problems.add("upstream.url is required");
            return null;
        }
        String text = raw.trim();
        try {
            URI uri = new URI(text);
            boolean httpScheme = "http".equalsIgnoreCase(uri.getScheme()) || "https".equalsIgnoreCase(uri.getScheme());
            if (!httpScheme || uri.getHost() == null) {
                problems.add("upstream.url must be an absolute http or https URL with a host, got '" + text + "'");
                return null;
            }
            return uri;
        } catch (URISyntaxException e) {
            problems.add("upstream.url is not a valid URL, got '" + text + "'");
            return null;
        }
    }

    private static String apiToken(Properties properties, List<String> problems) {
        String value = properties.getProperty("api.token");
        if (value == null || value.isBlank()) {
            problems.add("api.token is required");
            return null;
        }
        return value.trim();
    }

    private static int integer(Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String text = raw.trim();
        try {
            int value = Integer.parseInt(text);
            if (value < minimum) {
                problems.add(key + " must be at least " + minimum + ", got '" + text + "'");
                return defaultValue;
            }
            return value;
        } catch (NumberFormatException e) {
            problems.add(key + " must be a whole number, got '" + text + "'");
            return defaultValue;
        }
    }

    private static Duration requestTimeout(Properties properties, List<String> problems) {
        String raw = properties.getProperty("request.timeout");
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
