        if (!matcher.matches()) {
            problems.add("request.timeout must be a whole number followed by ms, s or m (for example 500ms, 30s, 2m), got '"
                    + text + "'");
            return DEFAULT_REQUEST_TIMEOUT;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            if (amount == 0) {
                problems.add("request.timeout must be greater than zero, got '" + text + "'");
                return DEFAULT_REQUEST_TIMEOUT;
            }
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
