package com.acme.relay.config;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ConfigLoaderTest {
    private static final String REQUIRED = """
            upstream.url=https://uplink.example.com/v1/events
            api.token=s3cret
            """;

    @TempDir
    Path dir;

    @Test
    void loadsEveryKey() throws IOException {
        Path file = write(REQUIRED + """
                worker.threads=8
                queue.capacity=250
                retry.max-attempts=5
                request.timeout=2m
                metrics.enabled=true
                """);

        ServiceConfig config = ConfigLoader.load(file);

        assertEquals(URI.create("https://uplink.example.com/v1/events"), config.upstream());
        assertEquals("s3cret", config.apiToken());
        assertEquals(8, config.workerThreads());
        assertEquals(250, config.queueCapacity());
        assertEquals(5, config.retryAttempts());
        assertEquals(Duration.ofMinutes(2), config.requestTimeout());
        assertTrue(config.metricsEnabled());
    }

    @Test
    void optionalKeysUseTheirDefaults() throws IOException {
        ServiceConfig config = ConfigLoader.load(write(REQUIRED));

        assertEquals(ConfigLoader.DEFAULT_WORKER_THREADS, config.workerThreads());
        assertEquals(ConfigLoader.DEFAULT_QUEUE_CAPACITY, config.queueCapacity());
        assertEquals(ConfigLoader.DEFAULT_RETRY_ATTEMPTS, config.retryAttempts());
        assertEquals(ConfigLoader.DEFAULT_REQUEST_TIMEOUT, config.requestTimeout());
        assertFalse(config.metricsEnabled());
    }

    @Test
    void parsesAllTimeoutUnits() throws IOException {
        assertEquals(
                Duration.ofMillis(500),
                ConfigLoader.load(write(REQUIRED + "request.timeout=500ms\n")).requestTimeout());
        assertEquals(
                Duration.ofSeconds(45),
                ConfigLoader.load(write(REQUIRED + "request.timeout=45s\n")).requestTimeout());
    }

    @Test
    void apiTokenIsRequired() throws IOException {
        Path file = write("upstream.url=https://uplink.example.com/v1/events\n");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertTrue(error.getMessage().contains("api.token"));
    }

    @Test
    void rejectsWorkerCountThatIsNotANumber() throws IOException {
        assertInvalid(REQUIRED + "worker.threads=four\n", "worker.threads must be a whole number, got 'four'");
    }

    @Test
    void rejectsEmptyValue() throws IOException {
        assertInvalid(REQUIRED + "worker.threads=\n", "worker.threads must be a whole number, got ''");
    }

    @Test
    void rejectsValuesBelowTheMinimum() throws IOException {
        assertInvalid(REQUIRED + "worker.threads=0\n", "worker.threads must be at least 1, got '0'");
        assertInvalid(REQUIRED + "retry.max-attempts=-1\n", "retry.max-attempts must be at least 0, got '-1'");
    }

    @Test
    void rejectsTimeoutWithoutAUnit() throws IOException {
        assertInvalid(REQUIRED + "request.timeout=30\n", "request.timeout must be a whole number followed by ms, s or m");
    }

    @Test
    void rejectsZeroTimeout() throws IOException {
        assertInvalid(REQUIRED + "request.timeout=0s\n", "request.timeout must be greater than zero");
    }

    @Test
    void rejectsMisspelledBoolean() throws IOException {
        assertInvalid(REQUIRED + "metrics.enabled=ture\n", "metrics.enabled must be true or false, got 'ture'");
    }

    @Test
    void rejectsUnknownKeys() throws IOException {
        assertInvalid(REQUIRED + "worker.thread=8\n", "unknown key 'worker.thread'");
    }

    @Test
    void rejectsUpstreamWithoutHttpScheme() throws IOException {
        assertInvalid("upstream.url=uplink.example.com/v1\napi.token=s3cret\n", "upstream.url must be an absolute http or https URL");
    }

    @Test
    void rejectsMissingUpstream() throws IOException {
        assertInvalid("api.token=s3cret\n", "upstream.url is required");
    }

    @Test
    void reportsEveryProblemAtOnce() throws IOException {
        Path file = write("upstream.url=https://uplink.example.com\nworker.threads=four\nqueue.capacity=big\n");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertTrue(error.getMessage().contains("api.token is required"), error.getMessage());
        assertTrue(error.getMessage().contains("worker.threads must be a whole number"), error.getMessage());
        assertTrue(error.getMessage().contains("queue.capacity must be a whole number"), error.getMessage());
    }

    @Test
    void rejectsMissingFile() {
        Path file = dir.resolve("does-not-exist.properties");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertTrue(error.getMessage().contains("cannot read configuration file"), error.getMessage());
    }

    private void assertInvalid(String content, String expectedMessage) throws IOException {
        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(write(content)));

        assertTrue(error.getMessage().contains(expectedMessage), error.getMessage());
    }

    private Path write(String content) throws IOException {
        return Files.writeString(dir.resolve("config.properties"), content);
    }
}
